<span class="line"><span style="--shiki-light:#A31515;--shiki-dark:#98C379;">      &quot;version&quot;</span><span style="--shiki-light:#000000;--shiki-dark:#ABB2BF;">: </span><span style="--shiki-light:#A31515;--shiki-dark:#98C379;">&quot;1.1.0&quot;</span></span>
